import json,sys,re,glob
S=sys.argv[1]
def load(fn):
    t=open(fn).read()
    # --paginate concatenates arrays
    t=t.replace('][',',')
    return json.loads(t)
iss=load(f'{S}/issues.json'); ic=load(f'{S}/icomments.json'); rc=load(f'{S}/rcomments.json')
print('issues+prs',len(iss),'issue comments',len(ic),'review comments',len(rc))
pat=re.compile(r'ravel|tengine',re.I)
for i in iss:
    kind='PR' if 'pull_request' in i else 'Issue'
    for field in ('title','body'):
        v=i.get(field) or ''
        n=len(pat.findall(v))
        if n: print(f"{kind} #{i['number']} {field}: {n} 件 (user={i['user']['login']})")
for c in ic:
    n=len(pat.findall(c.get('body') or ''))
    if n: print(f"comment {c['id']} on {c['issue_url'].split('/')[-1]}: {n} 件 (user={c['user']['login']}) {c['html_url']}")
for c in rc:
    n=len(pat.findall(c.get('body') or ''))
    if n: print(f"review comment {c['id']} on PR {c['pull_request_url'].split('/')[-1]}: {n} 件")
prs=[i['number'] for i in iss if 'pull_request' in i]
json.dump(prs,open(f'{S}/prs.json','w'))
EOF

